// pubspec.yaml:
//   flutter_bloc: ^8.1.4
//   equatable: ^2.0.5
//   bloc_concurrency: ^0.2.5   // debounce / droppable / sequential transformers
// dev_dependencies:
//   bloc_test: ^9.1.7
//   mocktail: ^1.0.3

import 'package:flutter_bloc/flutter_bloc.dart';
import 'package:equatable/equatable.dart';
import 'package:bloc_concurrency/bloc_concurrency.dart';
import 'package:stream_transform/stream_transform.dart';

// ────── Events (sealed) ──────
sealed class FeedEvent extends Equatable { const FeedEvent(); @override List<Object?> get props => []; }
class FeedLoadRequested extends FeedEvent { const FeedLoadRequested(); }
class FeedSearchChanged extends FeedEvent {
  final String q; const FeedSearchChanged(this.q); @override List<Object?> get props => [q];
}
class FeedRefreshed extends FeedEvent { const FeedRefreshed(); }

// ────── States (sealed) ──────
sealed class FeedState extends Equatable { const FeedState(); @override List<Object?> get props => []; }
class FeedInitial extends FeedState { const FeedInitial(); }
class FeedLoading extends FeedState { const FeedLoading(); }
class FeedLoaded extends FeedState {
  final List<Item> items; final String query;
  const FeedLoaded({required this.items, required this.query});
  @override List<Object?> get props => [items, query];
}
class FeedError extends FeedState {
  final String message; const FeedError(this.message); @override List<Object?> get props => [message];
}

// ────── Bloc ──────
EventTransformer<E> _debounce<E>(Duration d) =>
    (events, mapper) => events.debounce(d).switchMap(mapper);

class FeedBloc extends Bloc<FeedEvent, FeedState> {
  FeedBloc(this._repo) : super(const FeedInitial()) {
    on<FeedLoadRequested>(_onLoad);
    // Debounce keystrokes + drop stale results.
    on<FeedSearchChanged>(_onSearch, transformer: _debounce(const Duration(milliseconds: 300)));
    on<FeedRefreshed>(_onLoad, transformer: droppable());  // ignore taps while a refresh is running
  }

  final FeedRepository _repo;

  Future<void> _onLoad(FeedEvent e, Emitter<FeedState> emit) async {
    emit(const FeedLoading());
    try {
      final items = await _repo.list();
      emit(FeedLoaded(items: items, query: ''));
    } catch (err) {
      emit(FeedError('$err'));
    }
  }

  Future<void> _onSearch(FeedSearchChanged e, Emitter<FeedState> emit) async {
    emit(const FeedLoading());
    final items = await _repo.search(e.q);
    emit(FeedLoaded(items: items, query: e.q));
  }
}

// ────── UI ──────
class FeedScreen extends StatelessWidget {
  const FeedScreen({super.key});
  @override
  Widget build(BuildContext context) {
    return BlocProvider(
      create: (_) => FeedBloc(context.read())..add(const FeedLoadRequested()),
      child: Scaffold(
        appBar: AppBar(title: const Text('Feed')),
        body: Column(
          children: [
            TextField(
              onChanged: (q) => context.read<FeedBloc>().add(FeedSearchChanged(q)),
            ),
            Expanded(
              child: BlocConsumer<FeedBloc, FeedState>(
                listenWhen: (p, c) => c is FeedError,
                listener: (ctx, state) {
                  if (state is FeedError) ScaffoldMessenger.of(ctx)
                      .showSnackBar(SnackBar(content: Text(state.message)));
                },
                builder: (ctx, state) => switch (state) {
                  FeedInitial() || FeedLoading() => const Center(child: CircularProgressIndicator()),
                  FeedLoaded(:final items) => ListView.builder(
                    itemCount: items.length,
                    itemBuilder: (_, i) => ItemTile(items[i]),
                  ),
                  FeedError() => const Center(child: Text('Something went wrong')),
                },
              ),
            ),
          ],
        ),
      ),
    );
  }
}

import 'package:bloc_test/bloc_test.dart';
import 'package:mocktail/mocktail.dart';

class _MockRepo extends Mock implements FeedRepository {}

void main() {
  late FeedBloc bloc;
  late _MockRepo repo;

  setUp(() { repo = _MockRepo(); bloc = FeedBloc(repo); });

  blocTest<FeedBloc, FeedState>(
    'loads feed',
    setUp: () => when(() => repo.list()).thenAnswer((_) async => [Item(1)]),
    build: () => bloc,
    act: (b) => b.add(const FeedLoadRequested()),
    expect: () => [const FeedLoading(), FeedLoaded(items: [Item(1)], query: '')],
  );

  blocTest<FeedBloc, FeedState>(
    'search debounces 300ms',
    setUp: () => when(() => repo.search(any())).thenAnswer((_) async => [Item(9)]),
    build: () => bloc,
    act: (b) async {
      b.add(const FeedSearchChanged('a'));
      b.add(const FeedSearchChanged('ab'));
      b.add(const FeedSearchChanged('abc'));
      await Future.delayed(const Duration(milliseconds: 400));
    },
    verify: (_) => verify(() => repo.search('abc')).called(1),  // only last one
  );
}
